import React, { useEffect, useState } from "react";

export default function UserProfileCard({ token, me: initialMe = {}, activities = [], setMsg }) {
  const [me, setMe] = useState(initialMe);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!token) return;
    setLoading(true);

    fetch((process.env.REACT_APP_API || "http://localhost:4000") + "/api/users/me", {
      headers: { Authorization: `Bearer ${token}` },
    })
      .then((res) => res.json())
      .then((data) => {
        setMe(data || {});
        setLoading(false);
      })
      .catch((err) => {
        console.error(err);
        setMsg && setMsg("Failed to load profile");
        setLoading(false);
      });
  }, [token, setMsg]);

  if (loading) {
    return (
      <div style={{ background: "#fff", padding: 12, borderRadius: 10, textAlign: "center" }}>
        Loading profile...
      </div>
    );
  }

  return (
    <div
      style={{
        background: "#fff",
        padding: 16,
        borderRadius: 10,
        textAlign: "center",
        boxShadow: "0 4px 12px rgba(0,0,0,0.05)",
      }}
    >
      {/* Profile Icon */}
      <div
        style={{
          width: 70,
          height: 70,
          borderRadius: "50%",
          background: "#ddd",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          fontSize: 30,
          margin: "0 auto 10px",
          overflow: "hidden",
        }}
      >
        {me?.profileImage ? (
          <img
            src={me.profileImage}
            alt="Profile"
            style={{ width: "100%", height: "100%", objectFit: "cover" }}
          />
        ) : (
          me?.name?.charAt(0).toUpperCase() || "?"
        )}
      </div>

      <div style={{ fontWeight: "bold", fontSize: 16 }}>{me?.name || "No Name"}</div>
      <div style={{ fontSize: 13, color: "#666", marginBottom: 4 }}>{me?.email || "No Email"}</div>
      <div style={{ fontSize: 13, color: "#666", marginBottom: 8 }}>Role: {me?.role || "Member"}</div>

      {/* Activities */}
      <div style={{ textAlign: "left", marginTop: 10 }}>
        <strong>Activities Participated</strong>
        {activities?.length > 0 ? (
          activities.map((ev) => (
            <div
              key={ev.id}
              style={{ padding: 6, borderBottom: "1px solid #f0f0f0", fontSize: 12 }}
            >
              {ev.title} — {ev.type} {/* type: Volunteering or Donation */}
            </div>
          ))
        ) : (
          <div style={{ fontSize: 12, color: "#888" }}>No activities participated yet.</div>
        )}
      </div>
    </div>
  );
}
